// UserPromptSubmit playbook — quick heuristic on agent intent.
// MVP: keyword scan for non-best-practice signals (skip tests, quick hack,
// ignore RLS, disable auth). Future iteration: LLM call via aishaLlmRouter
// with cheap model (Haiku 4.5) for nuanced intent classification.
//
// CONTRACT: NEVER decision != allow on user prompts — user has priority.
const body = $input.first().json.body || $input.first().json;
if (body.event !== 'prompt_submit') {
  throw new Error(`WF_DIRIGENT_INTENT_ADVISOR expects event=prompt_submit, got ${body.event}`);
}
const prompt = String(body.user_prompt || '').toLowerCase();

const signals = [
  { pattern: /skip\s+tests?|--no-verify|disable\s+(?:tests?|gate)/, note: 'pomijí testy/gate' },
  { pattern: /quick\s+(?:hack|fix)|hot.?fix|workaround/, note: 'navrhuje quick hack' },
  { pattern: /ignore\s+rls|disable\s+rls|drop\s+(?:rls|policy)/, note: 'obchází RLS' },
  { pattern: /turn\s+off\s+auth|skip\s+auth|bypass\s+(?:auth|jwt)/, note: 'obchází autentikaci' },
  { pattern: /push\s+(?:--force|-f)|force.?push/, note: 'force push' },
  { pattern: /git\s+reset\s+--hard|drop\s+(?:table|database)/, note: 'destruktivní operace' }
];

const hits = signals.filter(s => s.pattern.test(prompt)).map(s => s.note);

let advisory = '';
if (hits.length > 0) {
  advisory = `⚠️ AISHA Advisor: detekuji v promptu signál — ${hits.join(', ')}. AISHA Development Law nepředepisuje, jen upozorňuje. Tvoje rozhodnutí.`;
}
return [{
  json: {
    advisory,
    decision: 'allow',
    _audit: { event: 'prompt_submit', story_id: body.story_id, session_id: body.session_id, hits }
  }
}];
